@section('scripts')<script>const b=document.getElementById('sms-body');function c(){const u=/[^\x00-\x7F]/.test(b.value),s=u?70:160,m=u?67:153,p=b.value.length<=s?(b.value.length?1:0):Math.ceil(b.value.length/m);chars.textContent=b.value.length+' کاراکتر';parts.textContent=p+' بخش'}b.oninput=c;c();document.getElementById('sms-mode').onchange=e=>schedule.hidden=e.target.value!=='scheduled';</script>@endsection
